function backToObjects(){closeEditorPopovers();document.querySelector('[data-workspace-mode="object"]').click();}
function finishContext(kind,save=true){
 try{
  if(kind==='walk')walkMode.stop();
  else if(kind==='plan')save?interiorWorkshop.finishEdit():interiorWorkshop.cancelEdit();
  else if(kind==='flora'){
   if(save&&(!floraDraftIsEmpty(floraEditor.draft)||project.parts.some(p=>p.id===floraEditor.draft.id)))floraEditor.finish();else floraEditor.close();
  }else if(kind==='cluster')save?metaballEditor.finish():metaballEditor.close();
  else if(kind==='route')save?routePanel.finishEdit():closeRouteWorkflow();
  else if(kind==='interior')save?interior3D.finishEdit():interior3D.cancelEdit();
  else if(kind==='platform')save?platformEditor.finishEdit():platformEditor.cancelEdit();
  else if(kind==='highway')save?highwayEditor.finishEdit():highwayEditor.cancelEdit();
  else if(kind==='shape'){stopShapeEditing();attachSelection();refresh();}
  else if(kind==='placement')cancelPlace();
  // Closing a plant returns to browsing plants in its existing Flora workspace.
  if(kind!=='flora'&&!floraEditor.active&&!metaballEditor.active&&!routeSession&&!interior3D.active&&!platformEditor.active&&!highwayEditor.active&&!interiorWorkshop.active)backToObjects();
 }catch(error){notify(error.message);}
 syncEditingContext();
}
function syncEditingContext(){
 const chosen=project.parts.filter(p=>selectedIds.has(p.id)),summary=describeSelection(chosen),p=chosen.find(p=>p.id===selected)||chosen[0];
 let context={mode:workspaceMode==='flora'?'flora-browse':workspaceMode,label:workspaceMode==='flora'?'Flora workspace':workspaceMode==='material'?'Material mode':'Object mode',...summary};
 const frameSelected=()=>{if(selectedIds.size)frame(selectionBox());};
 if(chosen.length)context.frame={label:'Frame selected',action:frameSelected};
 if(workspaceMode!=='object')context.hint=workspaceMode==='flora'?'Choose a plant, then Edit plant to change its parts.':'Painting surfaces · object positions are locked.';
 else if(!primaryAction.hidden&&!primaryAction.disabled)context.done={label:primaryAction.textContent,action:()=>primaryAction.click()};
 if(chosen.length)context.cancel={label:'Deselect',action:()=>{selected=null;selectedIds.clear();clearSurfaceSelection();attachSelection();refresh();}};
 let kind,editor,detail,part;
 if(walkMode.active){kind='walk';context={mode:'walk',label:'Walk view',name:'Exploring the scene',detail:'WASD to move · Mouse to look · Esc to return'};}
 else if(interiorWorkshop.active){kind='plan';editor=interiorWorkshop;}
 else if(floraEditor.placingAsset&&floraAsset(floraEditor.placingAsset)?.floraPreset){kind='flora-placement';part={name:floraAsset(floraEditor.placingAsset).name};detail='Click the ground to place a tree · Esc cancels';}
 else if(floraEditor.active){
  kind='flora';editor=floraEditor;part=editor.draft;const selection=editor.selection||{},organ=part.flora.organs.find(o=>o.id===selection.organ),branch=part.flora.branches.find(b=>b.id===selection.branch);
  detail=organ?(floraAsset(organ.asset)?.name||'Plant part')+' '+(part.flora.organs.indexOf(organ)+1)+(selection.morph?' · Shape control':selection.socket?' · Joint':' · Whole part'):branch&&!branch.anchor?(branch.name||'Branch')+' · Joint '+((selection.index??0)+1):'No plant part selected · click a part or joint';
   if(editor.placingAsset)detail='Placing '+floraAsset(editor.placingAsset).name+' · Click to place · Esc cancels';
 }else if(metaballEditor.active){kind='cluster';editor=metaballEditor;part=editor.draft;detail='Shape '+(part.metaballs.blobs.findIndex(b=>b.id===editor.selectedBlob)+1);}
 else if(routeSession){kind='route';part=routeSession.part;detail='Section '+(routePanel.selectedIndex+1)+' · '+(part.route.segments[routePanel.selectedIndex]?.kind||'Route');}
 else if(interior3D.active){kind='interior';editor=interior3D;}
 else if(platformEditor.active){kind='platform';editor=platformEditor;}
 else if(highwayEditor.active){kind='highway';editor=highwayEditor;}
 else if(shapeEditing){kind='shape';part=p;detail=shapeEditing.label;}
 else if(pending){kind='placement';part=pending;detail='Click to place · Esc cancels';}
 if(kind&&kind!=='walk'){
  part??=editor?.context?.part;detail??=editor?.context?.detail;
  const labels={'flora-placement':'Placing tree',flora:'Flora edit mode',interior:'Interior edit mode',plan:'Interior plan mode',route:part?.type==='wall-route'?'Wall edit mode':'Route edit mode',platform:'Platform edit mode',highway:'Road edit mode',cluster:'Object sculpt mode',shape:'Object shape mode',placement:'Placing object'};
  context={mode:kind,label:labels[kind],name:part?.name||'New object',detail:detail||'Whole object',hint:kind==='placement'?'Place the preview or cancel to return to selection.':kind==='shape'?'Shape edits are applied as you work.':'Editing inside this object · Done keeps your edits; Cancel discards this session.'};
  if(kind==='flora')context.frame={label:'Frame plant',action:()=>floraEditor.framePlant()};
  else if(kind==='interior')context.frame={label:'Frame room',action:()=>interior3D.frameFloor()};
   else if(kind==='route')context.frame={label:'Frame route',action:fitRoute,disabled:!routeSession.placed};
   else if(['platform','highway','cluster'].includes(kind))context.frame={label:'Frame '+({platform:'platform',highway:'road',cluster:'object'}[kind]),action:()=>editor.frame(),disabled:kind==='highway'&&!editor.context.placed};
 }
 if(kind){
  if(!['walk','placement','shape','flora','flora-placement'].includes(kind))context.save={label:'Save project (Ctrl+S)',shortLabel:'Save',action:saveProject};
  if(kind==='route'&&!routeSession.placed)context.hint='Place the route start in the scene to begin. Cancel returns to your scene.';
  if(kind==='highway'&&editor.context?.canFinish===false)context.hint='Draw a road stretch before finishing. Cancel returns to your scene.';
  const parent=kind==='route'&&routeSession?.interiorRoute||kind==='plan'&&interiorWorkshop.context?.returnToEditor;
  context.done={label:kind==='placement'?'Cancel placement':kind==='walk'?'Back to scene':kind==='flora'?'Done · Back to Flora':parent?'Done · Back to interior':'Done · Back to scene',action:()=>finishContext(kind),disabled:kind==='flora'&&floraEditor.dragging||kind==='route'&&!routeSession.placed||editor?.context?.canFinish===false};
  if(kind==='route'&&routeSession.entrancePreview)context.done.subtitle='Finish route + entrance';
  if(!['walk','placement','shape','flora-placement'].includes(kind))context.cancel={label:'Cancel edits',action:()=>finishContext(kind,false)};
 }
 if(kind==='flora-placement'){context.hint='Place a separate tree without attaching it to the current plant.';context.done={label:'Cancel placement',action:()=>floraEditor.endAssetDrag()};}
 if(kind==='flora'&&floraEditor.placingAsset)context.cancel={label:'Cancel placement',action:()=>floraEditor.endAssetDrag()};
 if(context.frame)context.frame.shortLabel='⌖';
 if(context.cancel)context.cancel.shortLabel=context.cancel.label==='Cancel edits'?'Cancel':context.cancel.label;
 if(context.done)context.done.shortLabel=context.done.label==='Done · Back to scene'?'Done → Scene':context.done.label==='Done · Back to Flora'?'Done → Flora':context.done.label==='Done · Back to interior'?'Done → Interior':context.done.label;
 const host=interiorWorkshop.active?interiorWorkshop.panel:viewportTopbar;
 if(editingContext.panel.parentNode!==host)host.prepend(editingContext.panel);
 editingContext.update(context);
}

